"use strict";(self.webpackChunksummerz=self.webpackChunksummerz||[]).push([[826597],{437412:(e,n,s)=>{s.r(n),s.d(n,{assets:()=>c,contentTitle:()=>o,default:()=>p,frontMatter:()=>i,metadata:()=>a,toc:()=>l});var r=s(474848),t=s(28453);const i={slug:"2004/08/01",title:"La Perouse",date:new Date("2004-08-01T23:00:00.000Z"),authors:"summerz",tags:["my life in Sydney"]},o=void 0,a={permalink:"/blog/2004/08/01",source:"@site/blog/2004/08/2004-08-01/index.md",title:"La Perouse",description:"\uc624\ub298\uc740 Geoffrey \uc544\uc800\uc528\uc5d0\uac8c \uc74c\uc545 \ud30c\uc77c \uc8fc\uae30\ub85c \ud574\uc11c \uc544\uce68 \uba39\uace0 \ub301\uc73c\ub85c \uac14\ub2e4. \ub0b4 mp3 player\ub97c \uc544\uc800\uc528 \ucef4\ud4e8\ud130\uc5d0 \uac78\uc5b4\ub1a8\ub294\ub370 3\uc2dc\uac04 \uac00\ub7c9 \uac78\ub9b0\ub2e4\uace0 \ud45c\uc2dc. -o- \ucee4\ud53c \ud55c\uc794 \ub9c8\uc2dc\uace0, \ub4dc\ub77c\uc774\ube0c \uac00\uae30\ub85c \uacb0\uc815.",date:"2004-08-01T23:00:00.000Z",tags:[{inline:!0,label:"my life in Sydney",permalink:"/blog/tags/my-life-in-sydney"}],readingTime:9.11,hasTruncateMarker:!0,authors:[{name:"summerz",imageURL:"https://github.com/summerz.png",key:"summerz"}],frontMatter:{slug:"2004/08/01",title:"La Perouse",date:"2004-08-01T23:00:00.000Z",authors:"summerz",tags:["my life in Sydney"]},unlisted:!1,prevItem:{title:"\ucc28\uc774.",permalink:"/blog/2004/08/01-2"},nextItem:{title:"looking for my flat",permalink:"/blog/2004/07/31"}},c={authorsImageUrls:[void 0]},l=[];function d(e){const n={a:"a",br:"br",img:"img",p:"p",strong:"strong",...(0,t.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.p,{children:"\uc624\ub298\uc740 Geoffrey \uc544\uc800\uc528\uc5d0\uac8c \uc74c\uc545 \ud30c\uc77c \uc8fc\uae30\ub85c \ud574\uc11c \uc544\uce68 \uba39\uace0 \ub301\uc73c\ub85c \uac14\ub2e4. \ub0b4 mp3 player\ub97c \uc544\uc800\uc528 \ucef4\ud4e8\ud130\uc5d0 \uac78\uc5b4\ub1a8\ub294\ub370 3\uc2dc\uac04 \uac00\ub7c9 \uac78\ub9b0\ub2e4\uace0 \ud45c\uc2dc. -o- \ucee4\ud53c \ud55c\uc794 \ub9c8\uc2dc\uace0, \ub4dc\ub77c\uc774\ube0c \uac00\uae30\ub85c \uacb0\uc815."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{target:"_blank","data-noBrokenLinkCheck":!0,href:s(331930).A+"",children:"20040801-1.jpg"}),(0,r.jsx)(n.br,{}),"\n\uc9d1\uc5d0\uc11c \uce74\uba54\ub77c\ub97c \ucc59\uaca8\ub4e4\uace0 La Perouse\uc5d0 \uac14\ub2e4 - Geoffrey \uc544\uc800\uc528, William, Vivien \uadf8\ub9ac\uace0 \ub098 (Catherine \uc544\uc8fc\uba38\ub2c8\ub294 \uc77c\ud558\uc2dc\ub290\ub77c \ud568\uaed8 \ubabb\uac00\uc2dc\uace0.). (Mission Impossible 2 \ucc0d\uc740 \uacf3\uc774\ub77c\uace0; ) \uadf8\ub7ec\ub2c8\uae4c Botany Bay\uc758 \uc77c\ubd80\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \uc5b4\uc81c \uc9c0\ub3c4\ucc45 \uc0ac\uc11c \uc7a0\uae50 \ubcf4\uba74\uc11c Botany Bay\uac00 \uac00\uae5d\uad6c\ub098 \uc2f6\uc5c8\ub294\ub370, \uc544\uc800\uc528 \ub355\ubd84\uc5d0 \ubc14\ub85c \ud604\uc7a5\ud559\uc2b5\uc744 \uc624\uac8c \ub410\ub2e4. ^^"]}),"\n",(0,r.jsx)(n.p,{children:"\uac14\ub2e4\uc640\uc11c\uc57c \uc54c\uc558\ub294\ub370, John\uc774 \ucc98\uc74c \uc5ec\uae30 \uc640\uc11c \ub098 \ub370\ub9ac\uace0 \ub2e4\ub2d0 \ub54c \uc5ec\uae30\ub3c4 \uc654\uc5c8\ub2e4. -_-; \uc124\uba85\ud574\uc8fc\uace0 \uadf8\ub7ac\ub294\ub370, \uc804\ud600 \uae30\uc5b5\uc774 \uc548\ub098\ub2e4\uac00 John\uc774 \uc774\uc57c\uae30\ub97c \uaebc\ub0b4\ub2c8\uae4c \uc5b4\ub834\ud48b\uc774 \uae30\uc5b5\uc774 \ub0ac\ub2e4. \uc5ec\uae30 \uc720\ub798\uc5d0 \ub300\ud55c \uc774\uc57c\uae30\ub3c4 \ud574\uc92c\ub358 \uac8c \uae30\uc5b5\uc774 \ub0ac\ub294\ub370, \ud574\uc92c\ub2e4\ub294 \uac83\ub9cc \uae30\uc5b5\ub098\uace0 \ub0b4\uc6a9\uc740 \uae30\uc5b5\uc774 \uc548\ub09c\ub2e4. -o- \ud504\ub791\uc2a4\uc640 \uc601\uad6d, Captain Cook\uc5d0 \uad00\ub828\ub41c \uc774\uc57c\uae30\uc600\ub294\ub370;;;"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{target:"_blank","data-noBrokenLinkCheck":!0,href:s(954533).A+"",children:"20040801-2.jpg"}),(0,r.jsx)(n.br,{}),"\n\uc870\uadf8\ub9cc \ub2e4\ub9ac\uc5d0 \ud3ed\ubc1c\ubb3c \ud130\uc9c4 \ud754\uc801\ub4e4 (\uadf8\ub0e5 \uae4c\ub9e3\uac8c \ud0c4 \uc790\uad6d\ub4e4)\ub3c4 \uc870\uae08\uc529 \ub0a8\uc544\uc788\ub2e4."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{target:"_blank","data-noBrokenLinkCheck":!0,href:s(27368).A+"",children:"20040801-3.jpg"}),(0,r.jsx)(n.br,{}),"\n\ub0a0\uc528\uac00 \ud750\ub9ac\ub2e4 \uac1c\ub2e4\ub97c \ubc18\ubcf5\ud588\ub294\ub370, \uc624\ud788\ub824 \uadf8\ub7ec\ub2c8 \uc9c0\ub09c\ubc88 Harbour Bridge \uac14\uc744 \ub54c\ucc98\ub7fc \uad6c\ub984\uc774 \uc5ed\ub3d9\uc801-_-\uc774\ub2e4. \uc544\uc800\uc528 \ub9d0\ub300\ub85c \uc815\ub9d0 \ucc28 \uc788\uc73c\uba74 - \uc5ec\ub984\uc5d0 \uc885\uc885 \uc624\uba74 \uc2dc\uc6d0\ud558\uac8c \ubc14\ub78c\ub3c4 \uc42c\uace0 \uc88b\uc744 \ub4ef. \uc5ec\uae30\ub294 \ud2b9\uc774\ud55c \uac8c \ubc14\ub2f7\uac00\uc5d0 \uac00\ub3c4 \uc9e0\ub0b4\uac00 \ubcc4\ub85c \uc548\ub09c\ub2e4. \uc544\uc800\uc528\uc640 \uc544\uc774\ub4e4 \uc0ac\uc9c4\ub3c4 \ucc0d\uc5b4\uc8fc\uace0, \uc544\uc774\ub4e4\uc774 \uac15\uc544\uc9c0\ub4e4 \ub370\ub9ac\uace0 \ub178\ub294 \uac83\ub3c4 \ucc0d\uace0... \ub098\uc911\uc5d0 \uc774\uba54\uc77c\ub85c \ubcf4\ub0b4\uc8fc\uae30\ub85c \ud588\ub2e4."]}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{src:s(851669).A+"",width:"225",height:"300"})}),"\n",(0,r.jsx)(n.p,{children:"\uacbd\uce58 #1"}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{src:s(947352).A+"",width:"225",height:"300"})}),"\n",(0,r.jsx)(n.p,{children:"Geoffrey \uc544\uc800\uc528"}),"\n",(0,r.jsx)(n.p,{children:"\uc0ac\uc2e4 \uc544\uc800\uc528\uac00 \uc544\uc800\uc528\ub77c\uace0 \ubd80\ub974\uc9c0 \ub9d0\ub77c\uace0 \ud588\ub2e4. -o- \ub098\uc774 \ub9ce\uc774 \ub4e0 \uac83 \uac19\uc774 \ub290\uaef4\uc9c4\ub2e4\uace0. \uadf8\ub0e5 '\ud615'\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uac8c \uc5b4\ub5bb\ub0d0\uace0 \uc7a0\uae50 \uc774\uc57c\uae30\ud588\uc5c8\ub294\ub370, '\ud615'\uc774\ub4e0 '\ud615\ub2d8'\uc774\ub4e0 '\uc0bc\ucd0c(^^)'\uc774\ub4e0 \uc554\ud2bc \uad1c\ucc2e\uc740 \ud638\uce6d\uc744 \uc0dd\uac01\ud574 \ubd10\uc57c\uaca0\ub2e4. \uadf8 \ub54c\uae4c\uc9c0\ub294 \uc544\uc800\uc528\ub2e4 -_-. \uadf8\ub098\uc800\ub098 \ud5c8\ub77d\uc5c6\uc774 \uc0ac\uc9c4 \uc62c\ub838\ub2e4\uace0 \ud654\ub0b4\uc2dc\uba74 \uc548\ub418\ub294\ub370;;; -o-"}),"\n",(0,r.jsx)(n.p,{children:"La Perouse\uc5d0 \uc654\ub2e4\uac14\ub2e4 \ud558\uba70 Geoffrey \uc544\uc800\uc528\uac00 \ud574\uc900 \uc5ec\ub7ec\uac00\uc9c0 \uc774\uc57c\uae30\ub4e4 - \uc804\ubd80 \uae30\uc5b5\uc740 \uc548\ub098\uace0, \uae30\uc5b5\ub098\ub294 \uac83\ub4e4\ub9cc -_-."}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"1"})," \uc885\uc885 \ub4a4\uc5d0 P \ub77c\uace0 \uc368\uc9c4 \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc778 \uc790\ub3d9\ucc28\ub4e4\uc744 \ubcfc \uc218 \uc788\ub294\ub370, \uadf8\uac8c \ucd08\ubcf4\uc6b4\uc804\uc774\ub77c\ub294 \ub73b\uc774\ub77c\uace0 \ud55c\ub2e4. \ube68\uac04 P\ub294 \uba74\ud5c8 \ub530\uace0 1\ub144\uc9f8, \ub179\uc0c9 P\ub294 \uadf8 \ub2e4\uc74c 1\ub144\uc9f8. \uc6b0\ub9ac\ub098\ub77c\ucc98\ub7fc '\uc6b4\uc804\uc740 \ucd08\ubcf4, \uac74\ub4e4\uba74 \ub78c\ubcf4' \uac19\uc740 \ud45c\uc2dc\ub97c \uc77c\uc77c\uc774 \ud558\uc9c0 \uc54a\uc544\ub3c4 \ub418\ub2c8 \ud6a8\uc728\uc801\uc778 \uac83 \uac19\uae30\ub3c4 \ud558\ub2e4."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"2"})," \uc6b0\ub9ac\ub098\ub77c\ucc98\ub7fc \uad50\ud1b5\ubc95\uaddc\ub97c \uc5b4\uae30\uba74 \ud3ec\uc778\ud2b8\ub97c \uae4c\uace0, \uc77c\uc815 \ud3ec\uc778\ud2b8 \uc774\uc0c1 \uae4c\uc774\uba74 \uba74\ud5c8 \ucde8\uc18c \ub4f1 \uac15\ub825\ud55c \uc81c\uc7ac\uac00 \ub4e4\uc5b4\uac04\ub2e4\uace0 \ud55c\ub2e4. \uc7ac\ubc0c\ub294 \uac74, \ubaa8\ubc94\uc6b4\uc804\uc790(?)\ub77c\ub4e0\uac00 \uad50\ud1b5 \ubc95\uaddc \uc704\ubc18\uc73c\ub85c \ucc98\uc74c \uac78\ub9b0 \uc6b4\uc804\uc790\ub4e4\uc740 \uc0ac\uc815\uc744 \uc798 \uc124\uba85\ud558\uba74 (\ub531\ud55c \uc0ac\uc815 \uc798 \uc124\uba85\ud574\uc11c \ud3b8\uc9c0\ub85c \ubcf4\ub0b8\ub2e4\uac70\ub098 \ud558\uba74) \uadf8\ub0e5 \ub118\uc5b4\uac04\ub2e4\uace0 \ud55c\ub2e4. -o- \ubaa8\ub4e0 \uac8c \ucca0\uc800\ud558\uac8c \uaddc\uaca9\ud654 \ub418\uc5b4\uc788\uc744 \uac83\ub9cc \uac19\uc740 \uc11c\ubc29(^^)\uc5d0 \ub300\ud55c \uc774\ubbf8\uc9c0\uac00 \ubc14\ub00c\ub294 \uc21c\uac04."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"3"})," \uac8c\ub2e4\uac00 - \ucd9c\ubc1c\ud558\uae30 \uc804\uc5d0 \uc774\uc57c\uae30\ud588\ub358 \uac74\ub370, Bing Lee\ub97c \ud3ec\ud568\ud55c \uba87\uba87 \uc804\uc790\uc81c\ud488 \ud30c\ub294 \uacf3\uc5d0\uc11c\ub294 \ud765\uc815 \uc798 \ud558\uba74 \ubb3c\uac74\uac12\uc744 \uae4e\uc744 \uc218\ub3c4 \uc788\ub2e8\ub2e4. -o- \uc624\uc624\uc624- \uc5b4\ub290 \uc815\ub3c4\uc758 \ub9c8\uc9c4\uc740 \uc138\uc77c\uc988\ub9e8\uc5d0\uac8c \ub5a8\uc5b4\uc9c0\uae30 \ub54c\ubb38\uc5d0 \uc774\ub9ac\uc800\ub9ac \uc798 \ud765\uc815\ud558\uba74 \uac00\ub2a5\ud558\ub2e4\uace0 \ud55c\ub2e4. \uc7ac\ubc0c\ub2e4."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"4"})," La Perouse \uac00\ub294 \uae38\uc5d0 \ucee8\ud14c\uc774\ub108 \uc6b4\ubc18\ud558\ub294 \ud070~ \ud06c\ub808\uc778\uc774 \uc788\ub294 \uacf3\uc744 \uc9c0\ub098\uac14\ub294\ub370 (\uacf5\ud56d \uadfc\ucc98), \uc544\uc800\uc528\uac00 \ub300\ud559\uc0dd \uc2dc\uc808 \uadf8 \ud06c\ub808\uc778 \ub9cc\ub4dc\ub294 \ud604\uc7a5\uc5d0\uc11c \uc77c \ud588\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc624\uc624\uc624- \uaf64 \ub192\uc544 \ubcf4\uc774\ub358\ub370, \ud2b9\ubcc4\ud55c \uc548\uc804\uc7a5\uce58\ub3c4 \uc5c6\uc774 \uc624\ub974\ub77d \ub0b4\ub9ac\ub77d \ud558\uba74\uc11c \uc77c \ud558\uc168\ub2e4\uace0. \uac8c\ub2e4\uac00 \ud638\uc8fc \uc560\ub4e4\uc740 \ud070 \ucca0\uadfc \ub4e4\uace0 \ub09c\uac04\ub3c4 \uc5c6\ub294 \uc678\ub098\ubb34 \ub2e4\ub9ac \uac19\uc740 \uacf3\uc744 \uc9c0\ub098\ub2e4\ub2c8\uba70 \uc77c \ud588\ub2e4\uace0. -o-"]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"5"})," \uadf8\ub7ec\uba74\uc11c \uacc1\ub4e4\uc774\uc2dc\ub294 \ud55c\ub9c8\ub514 - \uadf8 \uc77c \ud588\uc744 \ub54c\ub9cc \ud558\ub354\ub77c\ub3c4 \uadfc\ucc98\uc5d0 \uc544\ubb34 \uac83\ub3c4 \uc5c6\ub358 \ud669\ubb34\uc9c0\uc600\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc2e4 \ud638\uc8fc\uac00 \uac1c\ubc1c\ub41c\uc9c0 \uc5bc\ub9c8 \uc548\ub418\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\uc9c0. \ucf55- \uaf2c\uc9d1\uc5b4 \uc774\uc57c\uae30\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc5ec\uae30 \uc628\uc9c0 \uc5bc\ub9c8 \uc548 \ub41c \ub098\ub3c4 \uc885\uc885 \uadf8\ub7f0 \ub290\ub08c\uc744 \ubc1b\ub294\ub2e4. \ub9d0\ub85c\ub9cc \ub4e3\ub358 '\ud55c\uad6d\uc740 \uc7ac\ubc0c\ub294 \uc9c0\uc625, \uc11c\uc591\uc740 \uc2ec\uc2ec\ud55c \ucc9c\uad6d' \uc774\uc57c\uae30\uac00 \uc870\uae08\uc529 \ub290\uaef4\uc9c4\ub2e4\ub294 \ub73b."]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"6"})," \uac1c\uc778\uc801\uc73c\ub85c \uc5ec\uae30\uc758 \uc568\ubdf8\ub7f0\uc2a4 \uc81c\ub3c4\uac00 \ub9d8\uc5d0 \ub4e4\uc5c8\ub2e4. (000\uc774 \uae34\uae09\ud560 \ub54c \ub204\ub974\ub294 \ubc88\ud638\ub77c\ub294 \uac74 \uc54c\uace0 \uc788\uc5c8\ub2e4.) 000\uc744 \ub204\ub974\uba74 \uacbd\ucc30\uc774 \ud544\uc694\ud55c\uc9c0, \uc570\ubdf8\ub7f0\uc2a4\uac00 \ud544\uc694\ud55c\uc9c0, \uc18c\ubc29\ucc28\uac00 \ud544\uc694\ud55c\uc9c0 \ubb3c\uc5b4\ubcf8\ub2e4\uace0 \ud55c\ub2e4. \ud544\uc694\ud55c \uac70 \ub9d0\ud558\uace0 \uc8fc\uc18c \ub300\uba74 \ubc14\ub85c \ucd9c\ub3d9\ud55c\ub2e4\uace0. \uc570\ubdf8\ub7f0\uc2a4\uc758 \uacbd\uc6b0\ub294 \ucd9c\ub3d9\ud574\uc11c \uc77c\ub2e8 \uc751\uae09\uc870\uce58\ub97c \ud574\uc8fc\uace0 \uc6d0\ud558\uba74 \ubcd1\uc6d0\uc73c\ub85c \ub370\ub824\uac04\ub2e4\uace0 \ud55c\ub2e4. \ubcd1\uc6d0\uc73c\ub85c \ub370\ub824\uac00\uba74 \uc570\ubdf8\ub7f0\uc2a4 \ucd9c\ub3d9\ud55c \ube44\uc6a9\uc774 \ub4e4\uace0, \uadf8\ub0e5 \uc751\uae09\uc870\uce58\ub9cc \ubc1b\uace0 \ubcd1\uc6d0\uc5d0\ub294 \uc548\uac00\uace0 \ub3cc\ub824\ubcf4\ub0b4\uba74 \ubb34\ub8cc\ub77c\uace0 \ud55c\ub2e4. \uba4b\uc9c0\ub2e4 - \uc9dd\uc9dd\uc9dd. \uc774\uac74 \ubcf5\ud569\uc801\uc778 \ubb38\uc81c\ub77c\uace0 \uc0dd\uac01\ub418\ub294\ub370 - \uc6b0\ub9ac\ub098\ub77c\uc5d0\uc11c\ub294 \uae09\ud55c \uc77c \uc788\uc5b4\ub3c4 \ubcd1\uc6d0\ub9c8\ub2e4 \uc804\ud654\ud574\uc11c \uc570\ubdf8\ub7f0\uc2a4 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud558\uac70\ub098 \uc544\ub2c8\uba74 \uc54c\uc544\uc11c \ud0dd\uc2dc \uc7a1\uc544\ud0c0\uace0 \uac00\uc57c\ud558\uc9c0 \uc54a\ub098. \uae38\ub3c4 \ucc28\ub4e4\ub85c \uac00\ub4dd \ucc28\uc11c \uc570\ubdf8\ub7f0\uc2a4\uac00 \ube68\ub9ac \uac00\uace0 \uc2f6\uc5b4\ub3c4 \uac08 \uc218 \uc5c6\uc744 \ub54c\ub3c4 \uc788\uace0. \uc5ec\uae30\uc11c\ub294 \uc570\ubdf8\ub7f0\uc2a4\ub97c \ubd88\ub800\ub294\ub370 \ub2a6\uac8c \ub3c4\ucc29\ud560 \ub3d9\uc548 \ud658\uc790\uac00 \uc798\ubabb \ub418\uba74 \uc870\uc0ac \ub4e4\uc5b4\uac04\ub2e4\uace0 \ud55c\ub2e4 - \uc65c \ub2a6\uac8c \ub3c4\ucc29\ud588\ub294\uc9c0, \ub204\uad6c \ub54c\ubb38\uc5d0 \ubb34\uc5c7 \ub54c\ubb38\uc5d0 \ub2a6\uc740 \uac74\uc9c0."]}),"\n",(0,r.jsx)(n.p,{children:"\uc544\uc800\uc528 \uc9d1\uc5d0 \uac00\ub2c8 Catherine \uc544\uc8fc\uba38\ub2c8\ub3c4 \uc640 \uacc4\uc154\uc11c \ud568\uaed8 \uc810\uc2ec\uc744 \uba39\uc5c8\ub2e4. \uc810\uc2ec\uc740 \ub5a1\uad6d - \uad6d\ubb3c\uc774, \ub05d\ub0b4\uc918\uc694. :) \uc544\uc800\uc528 \ubd80\ubaa8\ub2d8\uc774 Lakemba\uc5d0\uc11c \ub3d9\ubc29\uc2dd\ud488\uc774\ub77c\ub294 \uc2dd\ud488\uc810\uc744 \ud558\uc2e0\ub2e4\uace0 \ud55c\ub2e4. (\uc7a5\uc0ac \uc798 \ub418\uc2dc\uae38 !!) Catherine \uc544\uc8fc\uba38\ub2c8\uac00 \uc8fc\ub9d0\uc5d0 \uac70\uae30\uc11c \uc77c \ub3c4\uc640 \ub4dc\ub9ac\uc2e0\ub2e4\ub294\ub370, \uc624\ub298 \uc77c\uc774 \uc880 \ub9ce\uc558\ub2e4\uace0 - \ucd94\uc11d\uc774 \uac00\uae4c\uc6cc\uc838\uc11c \uadf8\ub7f0 \uac83 \uac19\ub2e4\uace0 \ud558\uc2e0\ub2e4. \uc5ec\uae30\uc11c\ub3c4 \ucd94\uc11d\uc744 \ud06c\uac8c \uc9c0\ub0b4\ub294\ub370, \uc624\ud788\ub824 \uc124\ub0a0\ubcf4\ub2e4 \ub354 \ud06c\uac8c \uc9c0\ub0b8\ub2e4\uace0 \ud55c\ub2e4. \uc810\uc2ec \ub2e4 \uba39\uace0 \ub098\ub2c8 \uc804\uc1a1 \uc644\ub8cc. \uc544\uc800\uc528 \uac00\uc871\ub4e4\uc740 \uc5b4\ub514 \uac08\ub370\uac00 \uc788\uc5b4\uc11c \uac00\uace0, \ub09c \uc9d1\uc5d0 \ub4e4\uc5b4\uc654\ub2e4."}),"\n",(0,r.jsx)(n.p,{children:"\uc9d1\uc5d0 \uc624\ub2c8 \ub610 \uc544\ubb34\ub3c4 \uc5c6\ub2e4. ^^ \ud53c\uace4\ud574\uc11c \ud55c\uc228 \uc790\uace0 \ub098\ub2c8 \uc5b4\ub451\uc5b4\ub451. \uc77c\uc5b4\ub098\uc11c \uc800\ub141 \uba39\uace0 \ub3c4\uc2dc\ub77d \ucc59\uae30\uace0 \ubc29\uc5d0 \ub4e4\uc5b4\uc654\uc9c0. \uc624\ub298\uc740 \ubc14\ub78c\ub3c4 \uc42c\uace0 \uc815\ub9d0 \ud734\uc77c\ucc98\ub7fc \ubcf4\ub0c8\ub124."})]})}function p(e={}){const{wrapper:n}={...(0,t.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},331930:(e,n,s)=>{s.d(n,{A:()=>r});const r=s.p+"assets/files/20040801-1-e89430cca32b32cf7880104a3f4d55d5.jpg"},954533:(e,n,s)=>{s.d(n,{A:()=>r});const r=s.p+"assets/files/20040801-2-90c69131b89c741ff8cc3e68910b70fb.jpg"},27368:(e,n,s)=>{s.d(n,{A:()=>r});const r=s.p+"assets/files/20040801-3-ff275560e9e072c1931896206cf5a72e.jpg"},851669:(e,n,s)=>{s.d(n,{A:()=>r});const r=s.p+"assets/images/20040801-4-f939b19b5a53d0f7039514c0e34b9388.jpg"},947352:(e,n,s)=>{s.d(n,{A:()=>r});const r=s.p+"assets/images/20040801-5-c2fbe4421929584613315388b89dc481.jpg"},28453:(e,n,s)=>{s.d(n,{R:()=>o,x:()=>a});var r=s(296540);const t={},i=r.createContext(t);function o(e){const n=r.useContext(i);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),r.createElement(i.Provider,{value:n},e.children)}}}]);